package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public final class CompactRoadHistoryTest {
 static void reject(byte[] raw){try{new NativeRoadHistory(raw);throw new AssertionError("Malformed compact road accepted");}catch(IllegalArgumentException expected){}}
 public static void main(String[] args)throws Exception{byte[] raw=Files.readAllBytes(Paths.get(args[0]));int rejected=0;for(int at:new int[]{0,8,16,24,32,40,48,56,64,72,80,88,96,104,112,120}){byte[] bad=raw.clone();ByteBuffer.wrap(bad).order(ByteOrder.LITTLE_ENDIAN).putLong(at,-1);reject(bad);rejected++;}ByteBuffer h=ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN);int event=64;while(h.getLong(event)!=2)event+=(int)h.getLong(event+8);for(int at:new int[]{0,8,16,24,32,40,48,56,64,72,80,88}){byte[] bad=raw.clone();ByteBuffer.wrap(bad).order(ByteOrder.LITTLE_ENDIAN).putLong(event+at,-1);reject(bad);rejected++;}for(int at:new int[]{0,4,8,24,28,64}){byte[] bad=raw.clone();ByteBuffer.wrap(bad).order(ByteOrder.LITTLE_ENDIAN).putInt(event+96+at,-1);reject(bad);rejected++;}
 byte[] input=raw.clone();NativeRoadHistory history=new NativeRoadHistory(input);byte value=history.event(0).texture().get(0);java.util.Arrays.fill(input,(byte)0);if(history.event(0).texture().get(0)!=value||!history.event(0).texture().isReadOnly())throw new AssertionError("Mutable source history");try{history.samples(history.epoch+1,0,0);throw new AssertionError("Stale epoch accepted");}catch(IllegalArgumentException expected){}
 // Valid overlapping doubled row: original copies complete row0 then row1.
 ByteBuffer legacy=ByteBuffer.allocate(96+68+260).order(ByteOrder.LITTLE_ENDIAN);long[] header={0x314a524e,1,424,1,1,20,1,1,0,0x08000000,260,17};for(long x:header)legacy.putLong(x);int[] command=new int[17];command[1]=0x7fffffff;command[5]=0x08000000;command[6]=0x06000000;command[7]=130;command[10]=65536;command[16]=1;for(int x:command)legacy.putInt(x);for(int i=0;i<260;i++)legacy.put((byte)(i%251));NativeRoadHistory overlap=new NativeRoadHistory(legacy.array());NativeRoadHistory.Samples samples=overlap.samples(1,20,0);for(int cell=0;cell<500;cell++){int expected=(cell<240?cell:cell-240)%251;if((overlap.event(samples.event(cell)).texture().get(samples.offset(cell))&255)!=expected)throw new AssertionError("Doubled row order");}
 if(rejected!=34)throw new AssertionError("Incomplete rejection cases");System.out.println("PASS_COMPACT_ROAD_HISTORY malformed_rejected="+rejected+" overlap_cells=500 immutable=true");
 }
}
